insert into public.cpl_memory (slug, kind, title, summary, detail, plain, tags, source, related, status, scope, verified_by, verified_at, event_date, author)
values
 ('eacr-cip-sector-is-a-filter-aid-sam-2026-09-25', 'decision', 'Sam: the EACR''s CIP sector is a filter aid; sector it from your own analysis', 'Sam, 2026-09-25: the Exhibit Adoption view needs the CIP sector only for filtering and quick categorization, so the session may assign sectors from its own analysis rather than open the TOP/CIP question, which is its own project.', 'Verbatim, answering the session''s question of where to get course CIPs: ''CIP sector is best ... I don''t want this to be a big deal. We only need the CIP sector on this tab for filter and quick categorization. I would be just as happy if you used your own analysis from your knowledge to create the sectors yourself. I don''t want to get sucked into the top/CIP black hole, which is it''s own project.'' Applied the same day: the course-CIP ask (open-asks card 15) was withdrawn before it was published, and kb/reference/eacr_cip_title_rules.json (37 ordered title patterns plus an exact-title table) now sectors Standardized Assessment cards from their titles first and fills every card the TOP route leaves empty; cards without a sector 449 to 3, 84 exams moved to their subject, a random 25 all read right. Guard: tests/eacr_matrix_payload_test.py section 8c. Course and program CIPs stay with the TOP to CIP lane.', 'Sam decided the career-sector labels on the exhibit adoption page only need to be good enough to filter and group by, so the session sorted each exam into a sector by reading its title instead of chasing the official coding system, which Sam treats as its own project.', array['eacr','cip','scope','decision']::text[], 'Sam, 2026-09-25 (S288 SkyZ session)', array['top-is-unchecked-program-cip-is-reliable-sam-2026-09-25','a-program-cip-labels-the-program-not-its-courses','top-code-lookup-column-d-disagreed-with-its-titles-on-81-rows']::text[], 'verified', 'workstream-specific', 'Sam Lee (2026-09-25), recorded by SkyZ S288', now(), '2026-09-25'::date, 'SkyZ-s288')
on conflict (slug) do nothing;
update public.cpl_memory set detail = 'Built on kb/program_course_graph.json (colleges joined on the MIS code through kb/college_identity/<date>/crosswalk.json, course numbers compared without leading zeros, umbrella families 24 and 30 voting only when alone). It sectored 2,244 of 3,000 matrix rows against 2,621 for the TOP route, and its largest disagreement groups favored it (culinary 19 to 12, FAA pilot 47 to 49, water treatment 03 to 15, welding and ironworkers 15 to 48): those groups are career-technical, whose courses live in their own programs. The random sample told the other half: Elementary Italian to 12 Culinary, Beginning Chinese and AP Japanese to 05 Area Studies, Calculus 1 to 40 Physical Sciences, AP US Government to 22 Legal, Microsoft Word Expert to 51 Health. Read the course''s own CIP where one is set (no file or table we hold carries course CIPs; Supabase has CIP only on coci_college_programs), and use program membership to corroborate. For the EACR, Sam scoped the sector to a filter aid and the session sectored exams from their titles instead (row eacr-cip-sector-is-a-filter-aid-sam-2026-09-25). Note: docs/kb-notes/methodology-a-program-cip-labels-the-program-not-its-courses.md.'
 where slug = 'a-program-cip-labels-the-program-not-its-courses' and author = 'SkyZ-s288';
update public.cpl_memory set detail = 'Nothing read column D before #1681 (2026-09-24), which measured that 163 of 198 ids resolved and shipped; 46 of those 163 resolved to the wrong program, so a join rate is not a correctness rate. The 81: 35 codes that are no TOP code (Fire Technology 2130, Drafting 0909, Welding 0941) and 46 real codes naming another program (History 2203, which is Ethnic Studies; Political Science 2205, History; Nursing (RN) 1211, Polysomnography; Construction Crafts 0946, HVAC). kb/_correct_top_lookup_code4.py sets column D to the category of the TOP title column E names (kb/reference/top_categories.json, then the published crosswalk), settles 15 non-exact titles by hand and keeps row 144; receipt kb/receipts/top_code_lookup_code4_2026-09-25_s288.json; guard tests/top_code_lookup_code4_test.py (13 checks, in js-tests.yml beside tests/eacr_matrix_payload_test.py). Live since the 2026-09-25 13:16 UTC build, confirmed in Chromium: 890 to 379 unsectored rows (dropdown 449 cards), 328 cards re-sectored. 37 MAP TOP ids still have no row (100 cards); since 2026-09-25 the EACR sectors those cards from their titles instead (row eacr-cip-sector-is-a-filter-aid-sam-2026-09-25).'
 where slug = 'top-code-lookup-column-d-disagreed-with-its-titles-on-81-rows' and author = 'SkyZ-s288';
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select m.id, 'SkyZ-s288', case when m.slug = 'eacr-cip-sector-is-a-filter-aid-sam-2026-09-25' then 'create' else 'update' end,
       case when m.slug = 'eacr-cip-sector-is-a-filter-aid-sam-2026-09-25' then 'S288 SkyZ: Sam''s scoping ruling (kb/receipts/cpl_memory_2026-09-25_s288.sql, second block)'
            else 'S288 SkyZ: one sentence replaced after Sam''s scoping ruling withdrew card 15; before-value is the first block of kb/receipts/cpl_memory_2026-09-25_s288.sql' end,
